using System;

// PROGRAM: Eksperimen Two's Complement dan Integer Overflow
sbyte positiveFive = 5;
sbyte negativeFive = (sbyte)(~positiveFive + 1);

Console.WriteLine($"Positive: {positiveFive} (Biner: {Convert.ToString((byte)positiveFive, 2).PadLeft(8, '0')})");
Console.WriteLine($"Negative: {negativeFive} (Biner: {Convert.ToString((byte)negativeFive, 2).PadLeft(8, '0')})");

// Bukti Adder: 5 + (-5) harus menghasilkan 0
sbyte result = (sbyte)(positiveFive + negativeFive);
Console.WriteLine($"5 + (-5) = {result}");

// Demonstrasi Bahaya Overflow Finansial
int accountBalance = int.MaxValue;
Console.WriteLine($"Saldo Maksimal: Rp {accountBalance:N0}");
int overflowed = accountBalance + 1; // Unchecked overflow!
Console.WriteLine($"Setelah + 1 (Unchecked): Rp {overflowed:N0}");

