using System;

public class FinancialMath
{
    public static int? SafeAdd(int a, int b)
    {
        try
        {
            checked
            {
                return a + b;
            }
        }
        catch (OverflowException)
        {
            return null;
        }
    }

    public static void Main()
    {
        Console.WriteLine($"Normal: {SafeAdd(100, 200)}");
        Console.WriteLine($"Overflow: {SafeAdd(int.MaxValue, 1)}");
    }
}
